var mat = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/Flynn/Materials/M_SpriteLit3D.mat");
if (mat != null)
{
    UnityEngine.Debug.Log($"Shader: {mat.shader.name}");
    UnityEngine.Debug.Log($"Has _BumpMap: {mat.HasProperty("_BumpMap")}");
    if (mat.HasProperty("_BumpMap"))
    {
        var bumpTex = mat.GetTexture("_BumpMap");
        UnityEngine.Debug.Log($"_BumpMap texture: {(bumpTex != null ? bumpTex.name + " (" + bumpTex.GetType().Name + ")" : "null")}");
        if (bumpTex != null)
            UnityEngine.Debug.Log($"_BumpMap path: {UnityEditor.AssetDatabase.GetAssetPath(bumpTex)}");
    }
    UnityEngine.Debug.Log($"Has _MainTex: {mat.HasProperty("_MainTex")}");
    if (mat.HasProperty("_MainTex"))
    {
        var mainTex = mat.GetTexture("_MainTex");
        UnityEngine.Debug.Log($"_MainTex texture: {(mainTex != null ? mainTex.name : "null")}");
    }
}
else
{
    UnityEngine.Debug.Log("Material not found!");
}

