args.script:
var mat = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/Flynn/Materials/M_SpriteLit3D.mat");
var normalTex = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Texture>("Assets/Flynn/Sprites/run_n.png");
if (mat != null && normalTex != null)
{
    UnityEditor.Undo.RecordObject(mat, "Assign Normal Map");
    mat.SetTexture("_BumpMap", normalTex);
    UnityEditor.EditorUtility.SetDirty(mat);
    UnityEditor.AssetDatabase.SaveAssetIfDirty(mat);
    UnityEngine.Debug.Log($"Assigned _BumpMap: {normalTex.name}");
    // Verify
    var check = mat.GetTexture("_BumpMap");
    UnityEngine.Debug.Log($"_BumpMap after assign: {(check != null ? check.name : "null")}");
}
else
{
    UnityEngine.Debug.Log($"mat={mat}, normalTex={normalTex}");
}

