args.script:
var go = UnityEngine.GameObject.Find("Flynn");
if (go == null) { UnityEngine.Debug.Log("Flynn not found"); return; }

var driver = go.GetComponent<FlynnAnimationDriver>();
if (driver == null) { UnityEngine.Debug.Log("FlynnAnimationDriver not found"); return; }

var so = new UnityEditor.SerializedObject(driver);

// Find the Visual child to get its SpriteRenderer's shared material
var visual = go.transform.Find("Visual");
if (visual == null) { UnityEngine.Debug.Log("Visual child not found"); return; }

var sr = visual.GetComponent<UnityEngine.SpriteRenderer>();
var mat = sr != null ? sr.sharedMaterial : null;
UnityEngine.Debug.Log($"Shared material: {(mat != null ? mat.name : "null")}");

// Load normal maps
var idleNormal = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Texture>("Assets/Flynn/Sprites/idle_n.png");
var runNormal = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Texture>("Assets/Flynn/Sprites/run_n.png");
UnityEngine.Debug.Log($"idle_n: {(idleNormal != null ? "ok" : "null")}, run_n: {(runNormal != null ? "ok" : "null")}");

// Assign serialized fields
so.FindProperty("_spriteMaterial").objectReferenceValue = mat;
so.FindProperty("_idleNormal").objectReferenceValue = idleNormal;
so.FindProperty("_runNormal").objectReferenceValue = runNormal;
so.ApplyModifiedProperties();

UnityEngine.Debug.Log("All fields assigned!");

