using UnityEngine;
using UnityEditor;
using System.Linq;

// Find all animation clips under Flynn/Animations
var clips = AssetDatabase.FindAssets("t:AnimationClip", new[] { "Assets/Flynn/Animations" })
    .Select(g => AssetDatabase.GUIDToAssetPath(g))
    .Where(p => !p.Contains("/Idle8Dir/") && !p.Contains("/Run8Dir/")) // exclude the new 8-dir ones
    .ToList();

UnityEngine.Debug.Log($"=== Non-8dir Animation Clips ({clips.Count}) ===");
foreach (var clipPath in clips)
{
    var clip = AssetDatabase.LoadAssetAtPath<AnimationClip>(clipPath);
    if (clip == null) continue;

    var bindings = AnimationUtility.GetObjectReferenceCurveBindings(clip);
    var hasSpriteRefs = false;
    foreach (var binding in bindings)
    {
        var curve = AnimationUtility.GetObjectReferenceCurve(clip, binding);
        foreach (var frame in curve)
        {
            if (frame.value != null && frame.value is Sprite sprite)
            {
                var texPath = AssetDatabase.GetAssetPath(sprite);
                if (texPath.Contains("character_animations"))
                {
                    if (!hasSpriteRefs)
                    {
                        UnityEngine.Debug.Log($"\n{clipPath} → uses character_animations sprites:");
                        hasSpriteRefs = true;
                    }
                    UnityEngine.Debug.Log($"  {texPath} (sprite: {sprite.name})");
                }
            }
        }
    }
    if (!hasSpriteRefs)
    {
        // Check if it uses any sprites at all
        var anySprites = bindings.Any(b => AnimationUtility.GetObjectReferenceCurve(clip, b).Any(f => f.value is Sprite));
        if (anySprites)
            UnityEngine.Debug.Log($"\n{clipPath} → uses sprites from OTHER locations");
        else
            UnityEngine.Debug.Log($"\n{clipPath} → no sprite references");
    }
}

