args.script:
// Find ground objects and their render queues
var all = UnityEngine.Object.FindObjectsOfType<UnityEngine.MeshRenderer>();
foreach (var r in all)
{
    var mat = r.sharedMaterial;
    if (mat != null)
        UnityEngine.Debug.Log($"{r.gameObject.name}: queue={mat.renderQueue} shader={mat.shader.name} layer={r.gameObject.layer}");
}

// 1. Fix the pod render queue - push to 2451 to guarantee on-top of ground after alpha test pass
var podMat = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/Flynn/Materials/Crash_pod.mat");
if (podMat != null)
{
    // Push render queue slightly above AlphaTest default so it renders after ground
    podMat.renderQueue = 2460;
    UnityEditor.EditorUtility.SetDirty(podMat);
    UnityEditor.AssetDatabase.SaveAssetIfDirty(podMat);
    UnityEngine.Debug.Log($"Pod renderQueue set to {podMat.renderQueue}");
}

// 2. Create blob shadow quad under the pod
var pod = UnityEngine.GameObject.Find("Plane");
if (pod == null) { UnityEngine.Debug.Log("Plane not found"); return; }

// Create blob shadow as child of pod
var blob = new UnityEngine.GameObject("BlobShadow");
blob.transform.SetParent(pod.transform, false);

// Position it on the ground (local space, below the pod center)
// Pod is at y=1.147, ground is at y=0, so offset down in local space
blob.transform.localPosition = new UnityEngine.Vector3(0, -1.147f, 0.01f);
blob.transform.localRotation = UnityEngine.Quaternion.Euler(-90, 0, 0);
blob.transform.localScale = new UnityEngine.Vector3(1.2f, 1.2f, 1.2f);

// Add quad mesh
var mf = blob.AddComponent<UnityEngine.MeshFilter>();
mf.sharedMesh = UnityEngine.Resources.GetBuiltinResource<UnityEngine.Mesh>("Quad.fbx");

var mr = blob.AddComponent<UnityEngine.MeshRenderer>();
mr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
mr.receiveShadows = false;
mr.lightProbeUsage = UnityEngine.Rendering.LightProbeUsage.Off;
mr.reflectionProbeUsage = UnityEngine.Rendering.ReflectionProbeUsage.Off;

// Create a blob shadow material
var blobMat = new UnityEngine.Material(UnityEditor.Shader.Find("Universal Render Pipeline/Lit"));
blobMat.SetFloat("_Surface", 1f); // Transparent
blobMat.SetFloat("_Blend", 0f);  // Alpha blend
blobMat.SetFloat("_AlphaClip", 0f);
blobMat.SetInt("_ZWrite", 0);
blobMat.renderQueue = 2999; // Just before transparent
blobMat.EnableKeyword("_SURFACE_TYPE_TRANSPARENT");
blobMat.DisableKeyword("_ALPHATEST_ON");

// Load shadow circle texture
var shadowTex = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Texture>("Assets/Flynn/Art/Shadows/ShadowCircle.png");
if (shadowTex != null)
{
    blobMat.SetTexture("_MainTex", shadowTex);
    blobMat.color = new UnityEngine.Color(0, 0, 0, 0.6f);
    UnityEngine.Debug.Log($"Shadow texture assigned: {shadowTex.name}");
}
else
{
    blobMat.color = new UnityEngine.Color(0, 0, 0, 0.5f);
    UnityEngine.Debug.Log("No shadow texture found, using solid color");
}

// Double-sided so it's visible from above
blobMat.SetInt("_Cull", 0);
blobMat.doubleSidedGI = true;

mr.sharedMaterial = blobMat;

// Save material
if (!UnityEditor.AssetDatabase.IsValidFolder("Assets/Flynn/Materials/Shadows"))
    UnityEditor.AssetDatabase.CreateFolder("Assets/Flynn/Materials", "Shadows");
UnityEditor.AssetDatabase.CreateAsset(blobMat, "Assets/Flynn/Materials/Shadows/M_BlobShadow.mat");
UnityEditor.AssetDatabase.SaveAssetIfDirty(blobMat);

UnityEngine.Debug.Log($"Blob shadow created at local pos: {blob.transform.localPosition}");
UnityEngine.Debug.Log($"Blob shadow world pos: {blob.transform.position}");

