var pod = UnityEngine.GameObject.Find("Plane");
if (pod == null) { UnityEngine.Debug.Log("Plane not found"); return; }

// Remove BillboardRegistration
var br = pod.GetComponent<BillboardRegistration>();
if (br != null)
{
    UnityEngine.Object.DestroyImmediate(br);
    UnityEngine.Debug.Log("Removed BillboardRegistration");
}

// Calculate the Y rotation to face the camera
var cam = UnityEngine.Camera.main;
if (cam != null)
{
    var dirToCamera = cam.transform.position - pod.transform.position;
    var flatDir = new UnityEngine.Vector3(dirToCamera.x, 0, dirToCamera.z).normalized;
    var yAngle = UnityEngine.Quaternion.LookRotation(flatDir).eulerAngles.y;

    // Set fixed rotation: 90° X (upright), Y facing camera, Z=0
    pod.transform.rotation = UnityEngine.Quaternion.Euler(90, yAngle, 0);
    UnityEngine.Debug.Log($"Camera dir Y: {yAngle:F1}°");
    UnityEngine.Debug.Log($"Pod rotation: {pod.transform.rotation.eulerAngles}");
}

