// Create blob shadow as independent object
var blob = new UnityEngine.GameObject("Pod_BlobShadow");

// Place on ground under the pod
blob.transform.position = new UnityEngine.Vector3(pod.transform.position.x, 0.02f, pod.transform.position.z);
blob.transform.rotation = UnityEngine.Quaternion.Euler(-90, 0, 0);
blob.transform.localScale = new UnityEngine.Vector3(2.0f, 2.0f, 2.0f);

var mf = blob.AddComponent<UnityEngine.MeshFilter>();
mf.sharedMesh = UnityEngine.Resources.GetBuiltinResource<UnityEngine.Mesh>("Quad.fbx");

var mr = blob.AddComponent<UnityEngine.MeshRenderer>();
mr.shadowCastingMode = UnityEngine.Rendering.ShadowCastingMode.Off;
mr.receiveShadows = false;

var blobMat = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/Flynn/Materials/Shadows/M_BlobShadow.mat");
if (blobMat != null)
{
    mr.sharedMaterial = blobMat;
    UnityEngine.Debug.Log($"Blob shadow material: {blobMat.name}");
}
else
{
    UnityEngine.Debug.Log("M_BlobShadow not found, creating...");
}

UnityEngine.Debug.Log($"BlobShadow created at {blob.transform.position}");

