args.script:
// Check the ground shader and see if we can disable ZWrite
var ground = UnityEngine.GameObject.Find("Ground");
if (ground == null) { UnityEngine.Debug.Log("Ground not found"); return; }

var gmr = ground.GetComponent<UnityEngine.MeshRenderer>();
var gmat = gmr.sharedMaterial;
UnityEngine.Debug.Log($"Ground shader: {gmat.shader.name}");
UnityEngine.Debug.Log($"Ground queue: {gmat.renderQueue}");
UnityEngine.Debug.Log($"Ground has _ZWrite: {gmat.HasProperty("_ZWrite")}");

// Check ALL terrain/ground-like objects - they all use the same shader
var shader = gmat.shader;
var allUsingShader = new System.Collections.Generic.List<string>();
foreach (var mr in UnityEngine.Object.FindObjectsOfType<UnityEngine.MeshRenderer>())
{
    if (mr.sharedMaterial != null && mr.sharedMaterial.shader == shader)
        allUsingShader.Add(mr.gameObject.name);
}
UnityEngine.Debug.Log($"\nObjects using '{shader.name}': {allUsingShader.Count}");
foreach (var name in allUsingShader)
    UnityEngine.Debug.Log($"  {name}");

// Check the camera and pod positions to understand the depth relationship
var cam = UnityEngine.Camera.main;
var pod = UnityEngine.GameObject.Find("Plane");

UnityEngine.Debug.Log($"Camera pos: {cam.transform.position}");
UnityEngine.Debug.Log($"Camera ortho: {cam.orthographic}");
UnityEngine.Debug.Log($"Camera near: {cam.nearClipPlane}, far: {cam.farClipPlane}");
UnityEngine.Debug.Log($"Pod pos: {pod.transform.position}");

// Check the ground's actual Y position
var ground = UnityEngine.GameObject.Find("Ground");
UnityEngine.Debug.Log($"Ground pos: {ground.transform.position}");
UnityEngine.Debug.Log($"Ground scale: {ground.transform.localScale}");

// What's the pod's distance from camera vs ground's distance from camera?
float podDist = -UnityEngine.Vector3.Dot(pod.transform.position - cam.transform.position, cam.transform.forward);
float groundDist = -UnityEngine.Vector3.Dot(ground.transform.position - cam.transform.position, cam.transform.forward);
UnityEngine.Debug.Log($"Pod depth from camera: {podDist:F3}");
UnityEngine.Debug.Log($"Ground depth from camera: {groundDist:F3}");
UnityEngine.Debug.Log($"Pod is {(podDist < groundDist ? "CLOSER" : "FARTHER")} to camera than ground");

