// Disable ZWrite on the ground material via MaterialIntProperty
var ground = UnityEngine.GameObject.Find("Ground");
var gmr = ground.GetComponent<UnityEngine.MeshRenderer>();

// Create a MaterialPropertyBlock to override ZWrite
var block = new UnityEngine.MaterialPropertyBlock();
gmr.GetPropertyBlock(block);

// The shader graph doesn't expose ZWrite, but we can override it 
// by using SetInt on the material directly (URP reads _ZWrite from material)
// OR we just set it on the shared material

// Actually, for Shader Graph shaders, ZWrite is controlled in the shader itself.
// The simplest approach: duplicate the material and create a custom shader variant.

// Let me check: can we just set the material's render queue and ZWrite via script?
var gmat = gmr.sharedMaterial;
UnityEngine.Debug.Log($"Ground mat: {gmat.name}, shader: {gmat.shader.name}");

// Try setting _ZWrite on the material instance (not shared)
var matInstance = new UnityEngine.Material(gmat);
matInstance.SetInt("_ZWrite", 0);
gmr.material = matInstance;
UnityEngine.Debug.Log($"Set ground ZWrite=Off on instance");

// Verify
UnityEngine.Debug.Log($"Ground _ZWrite: {gmr.material.GetInt("_ZWrite")}");

// Clean up: destroy the leaked instance and do it properly via the shared material
var ground = UnityEngine.GameObject.Find("Ground");
var gmr = ground.GetComponent<UnityEngine.MeshRenderer>();

// Destroy the leaked instance
if (gmr.material != gmr.sharedMaterial)
{
    var leaked = gmr.material;
    gmr.sharedMaterial = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/Flynn/Materials/PB_Ground.mat");
    UnityEngine.Object.DestroyImmediate(leaked);
}

// Now properly set ZWrite Off on the shared material
var gmat = gmr.sharedMaterial;
UnityEngine.Debug.Log($"Ground material: {gmat.name}");

// Set _ZWrite via SerializedObject to avoid the material instance leak
var so = new UnityEditor.SerializedObject(gmat);
var zWriteProp = so.FindProperty("m_CustomMixedZWrite");
if (zWriteProp != null)
{
    UnityEngine.Debug.Log($"Found m_CustomMixedZWrite: {zWriteProp.boolValue}");
    zWriteProp.boolValue = false;
    so.ApplyModifiedProperties();
    UnityEditor.EditorUtility.SetDirty(gmat);
    UnityEditor.AssetDatabase.SaveAssetIfDirty(gmat);
    UnityEngine.Debug.Log("ZWrite disabled via SerializedObject");
}
else
{
    UnityEngine.Debug.Log("m_CustomMixedZWrite not found, trying _ZWrite...");
    gmat.SetInt("_ZWrite", 0);
    UnityEditor.EditorUtility.SetDirty(gmat);
    UnityEditor.AssetDatabase.SaveAssetIfDirty(gmat);
    UnityEngine.Debug.Log($"_ZWrite set to: {gmat.GetInt("_ZWrite")}");
}

