args.script:
// Clean up all leaked instances
var ground = UnityEngine.GameObject.Find("Ground");
var gmr = ground.GetComponent<UnityEngine.MeshRenderer>();

// Force back to shared material
var sharedMat = UnityEditor.AssetDatabase.LoadAssetAtPath<UnityEngine.Material>("Assets/Flynn/Materials/PB_Ground.mat");
if (sharedMat != null)
{
    gmr.sharedMaterial = sharedMat;
    UnityEngine.Debug.Log($"Restored shared material: {sharedMat.name}");
}

// Now set ZWrite on the actual asset
var so = new UnityEditor.SerializedObject(sharedMat);

// Find the ZWrite property in shader graph materials
var prop = so.GetIterator();
bool found = false;
while (prop.Next(true))
{
    if (prop.name.Contains("ZWrite") || prop.name.Contains("zwrite"))
    {
        UnityEngine.Debug.Log($"Found property: {prop.name} = {prop.boolValue} (type: {prop.propertyType})");
        if (prop.propertyType == UnityEditor.SerializedPropertyType.Boolean)
        {
            prop.boolValue = false;
            found = true;
        }
    }
}

if (found)
{
    so.ApplyModifiedProperties();
    UnityEditor.EditorUtility.SetDirty(sharedMat);
    UnityEditor.AssetDatabase.SaveAssetIfDirty(sharedMat);
    UnityEngine.Debug.Log("ZWrite disabled on ground material asset");
}
else
{
    // Fallback: set _ZWrite directly on the material
    sharedMat.SetInt("_ZWrite", 0);
    UnityEditor.EditorUtility.SetDirty(sharedMat);
    UnityEditor.AssetDatabase.SaveAssetIfDirty(sharedMat);
    UnityEngine.Debug.Log($"Set _ZWrite=0 on asset (value: {sharedMat.GetInt("_ZWrite")})");
}

