args.script:
var pod = UnityEngine.GameObject.Find("Plane");
var player = UnityEngine.GameObject.Find("Player");

UnityEngine.Debug.Log($"Pod pos: {pod.transform.position}");
UnityEngine.Debug.Log($"Player pos: {player.transform.position}");

// Check if player is actually in front of the pod (closer to camera)
var cam = UnityEngine.Camera.main;
var podDepth = UnityEngine.Vector3.Dot(pod.transform.position - cam.transform.position, cam.transform.forward);
var playerDepth = UnityEngine.Vector3.Dot(player.transform.position - cam.transform.position, cam.transform.forward);
UnityEngine.Debug.Log($"Pod camera-relative depth: {podDepth:F2}");
UnityEngine.Debug.Log($"Player camera-relative depth: {playerDepth:F2}");
UnityEngine.Debug.Log($"Player is {(playerDepth < podDepth ? "CLOSER" : "FARTHER")} to camera");

// The Visual child of the player is a SpriteRenderer with sorting order 10000
// MeshRenderers don't use sorting order the same way
// So the pod (MeshRenderer, queue 2460) draws BEFORE the sprite (sorting order 10000)
// This means the sprite should render on top of the pod

// But other MeshRenderer objects at queue 2000 draw BEFORE the pod
// Since the pod has ZWrite Off and ZTest LEqual, it should respect their depth
// But the pod's Offset bias might push it in front

UnityEngine.Debug.Log("\nOffset -1,-1 creates a depth bias that shifts the pod slightly toward the camera.");
UnityEngine.Debug.Log("This may cause it to render in front of objects that are very close in depth.");

